(3,13,'Rajut Ibu Rina','kerajinan','Tas dan dompet rajut buatan tangan dengan bahan katun lokal. Bisa pesan warna sesuai keinginan.','assets/img/lapak-placeholder.svg','081230002222','tayang',NULL,1,'2026-10-12 09:00:00'),
(4,17,'Sayur Segar Pak Agus','pertanian','Sayuran hidroponik yang dipanen setiap pagi: selada, kangkung, dan bayam.','assets/img/lapak-placeholder.svg','081230003333','tayang',NULL,1,'2026-10-13 09:00:00'),
(5,21,'Katering Dewi','makanan','Katering harian untuk keluarga dan kantor, tersedia menu rendah minyak.','assets/img/lapak-placeholder.svg','081230004444','tayang',NULL,1,'2026-10-14 09:00:00'),
(6,25,'Keripik Singkong Bu Lilis','makanan','Keripik singkong aneka rasa, digoreng tanpa pengawet. Tersedia kemasan 200 gram.','assets/img/lapak-placeholder.svg','081230005555','menunggu',NULL,1,'2026-10-15 09:00:00'),
(7,29,'Laundry Kilat Pak Eko','jasa','Laundry harian dengan layanan antar jemput untuk warga sekitar RW.','assets/img/lapak-placeholder.svg','081230006666','menunggu',NULL,1,'2026-10-16 09:00:00'),
(8,33,'Meja Kayu Pak Tono','kerajinan','Meja dan rak kayu sederhana untuk rumah, dibuat sesuai ukuran pesanan.','assets/img/lapak-placeholder.svg','081230007777','ditolak','Foto produk belum jelas, silakan unggah ulang.',1,'2026-10-17 09:00:00');
INSERT INTO announcements (id, author_id, rw_id, tipe, judul, isi, tanggal_acara, lokasi, siaga, sematkan, berlaku_sampai, created_at) VALUES
(1,1,NULL,'pengumuman','Siaga banjir: siapkan tas darurat','Prakiraan hujan lebat tiga hari ke depan. Siapkan tas darurat berisi dokumen penting, obat pribadi, senter, dan air minum. Catat nomor titik kumpul terdekat dan pantau pengumuman ini.',NULL,NULL,1,1,DATE_ADD(CURDATE(), INTERVAL 7 DAY),NOW()),
(2,2,5,'pengumuman','Jadwal angkut sampah RW 05','Pengangkutan sampah rumah tangga dimajukan menjadi pukul 06.00 mulai pekan depan. Mohon sampah diletakkan di depan rumah sejak pukul 05.30 dalam kantong tertutup.',NULL,NULL,0,0,NULL,NOW()),
(3,2,5,'agenda','Kerja bakti saluran air','Bersama membersihkan saluran air di sepanjang Jl. Melati agar tidak tersumbat saat musim hujan. Bawa cangkul atau sekop bila punya. Konsumsi disediakan warga.',DATE_ADD(CURDATE(), INTERVAL 3 DAY),'Balai RW 05',0,0,NULL,NOW()),
(4,2,5,'agenda','Pembagian pangan bulanan','Pembagian paket pangan untuk warga terdata. Bawa kartu warga dan datang sesuai jadwal agar antrean tertib.',DATE_ADD(CURDATE(), INTERVAL 7 DAY),'Posyandu RW 05',0,0,NULL,NOW()),
(5,1,NULL,'agenda','Pelatihan usaha warga','Pelatihan pencatatan keuangan sederhana dan foto produk untuk lapak usaha warga. Terbuka untuk semua RW, kuota 30 orang. Daftar lewat petugas RW masing-masing.',DATE_ADD(CURDATE(), INTERVAL 14 DAY),'Kantor RW 05',0,0,NULL,NOW()),
(6,2,5,'tips','Pisahkan sampah sejak dari rumah','Sampah plastik, kertas, logam, dan kaca yang dipisahkan akan dihargai lebih baik di bank sampah. Bilas kemasan bekas makanan agar tidak berbau dan mudah ditimbang.',NULL,NULL,0,0,NULL,NOW());
